<div class="page-actions"><div><h2>Gallery Manager</h2><p>Upload, caption, reorder, activate or remove photos without editing code.</p></div></div><div class="management-layout"><section class="admin-panel sticky-form"><div class="panel-head"><h3>Upload / Edit Image</h3><button class="outline-link mini" type="button" data-gallery-reset>Clear</button></div><form method="post" enctype="multipart/form-data" action="<?=url('admin/gallery/save')?>" class="admin-form" data-gallery-form><?=csrf_field()?><input type="hidden" name="id"><label class="full"><span>Title *</span><input name="title" required maxlength="180"></label><label><span>Category</span><input name="category" maxlength="100" placeholder="Community"></label><label><span>Display Order</span><input type="number" name="sort_order" value="0"></label><label class="full"><span>Caption</span><textarea name="caption" rows="4" maxlength="700"></textarea></label><label class="full"><span>Image</span><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"><small class="helper">Recommended 1600 × 1200 px (4:3). Gallery frames use automatic cover fitting.</small></label><label class="toggle-line full"><input type="checkbox" name="is_active" value="1" checked><span>Active / visible in website gallery</span></label><button class="admin-btn full">Save Gallery Item</button></form></section><section class="gallery-admin-grid"><?php foreach($items as $g):$payload=e(json_encode(['id'=>$g['id'],'title'=>$g['title'],'category'=>$g['category'],'sort_order'=>$g['sort_order'],'caption'=>$g['caption'],'is_active'=>(int)$g['is_active']],JSON_HEX_APOS|JSON_HEX_QUOT));?><article class="gallery-admin-card"><img src="<?=e(safe_image($g['image_path']))?>" alt=""><div><span class="status-badge <?=$g['is_active']?'active':'inactive'?>"><?=$g['is_active']?'Active':'Inactive'?></span><h3><?=e($g['title'])?></h3><p><?=e($g['caption']??'')?></p><div class="card-admin-actions"><button class="outline-link" type="button" data-gallery-edit='<?=$payload?>'>Edit</button><form method="post" action="<?=url('admin/gallery/delete')?>" data-confirm="Delete this gallery image?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$g['id']?>"><button class="danger-link">Delete</button></form></div></div></article><?php endforeach;?><?php if(!$items):?><div class="admin-panel empty-card">No gallery images yet.</div><?php endif;?></section></div>

